import { readFileSync } from 'node:fs';
const css = readFileSync('node_modules/@gravity-ui/uikit/styles/styles.css','utf8');
function block(sel){ const i=css.indexOf(sel+' {'); const j=css.indexOf('}', i); return css.slice(i, j); }
function vars(txt){ const m={}; for (const l of txt.matchAll(/(--g-color-[a-z0-9-]+):\s*([^;]+);/g)) m[l[1]]=l[2].trim(); return m; }
function resolve(m,v,d=0){ if(d>10) return v; return v.replace(/var\((--[a-z0-9-]+)\)/g,(_,n)=> m[n]? resolve(m,m[n],d+1): _); }
for (const t of ['light','dark']) {
  const m = vars(block('.g-root_theme_'+t));
  const want = ['base-background','base-float','base-generic','base-generic-hover','base-simple-hover','text-primary','text-secondary','text-hint','text-complementary','line-generic','line-generic-solid','line-generic-accent','infographics-axis','infographics-tooltip-bg','base-float-hover','sfx-shadow','text-info','text-positive','text-danger','text-warning','text-misc','text-utility','text-brand','line-focus'];
  console.log('== '+t);
  for (const w of want) console.log(w.padEnd(26), resolve(m, m['--g-color-'+w]||'?'));
  for (const hue of ['blue','green','orange','purple','red','yellow','cool-grey']) {
    const row=[]; for (const s of [400,450,500,550,600,650,700]) row.push(s+':'+resolve(m,m[`--g-color-private-${hue}-${s}-solid`]||'?'));
    console.log(hue.padEnd(10), row.join('  '));
  }
}
EOF
