import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 960, height: 560 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:4173/', { waitUntil: 'networkidle' });
await page.screenshot({ path: '/tmp/shots/light.png' });
// hover a point near the middle of the plot
const svg = await page.locator('svg.line-chart__svg').boundingBox();
await page.mouse.move(svg.x + svg.width * 0.55, svg.y + svg.height * 0.5);
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/shots/light-hover.png' });
await page.getByRole('radio', { name: 'Тёмная' }).click();
await page.mouse.move(svg.x + svg.width * 0.8, svg.y + svg.height * 0.5);
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/shots/dark-hover.png' });
await page.mouse.move(0, 0);
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/shots/dark.png' });
await page.getByRole('button', { name: 'Таблица' }).click();
await page.screenshot({ path: '/tmp/shots/dark-table.png', fullPage: true });
// keyboard: focus chart, arrow left
await page.getByRole('button', { name: 'График' }).click();
await page.locator('svg.line-chart__svg').focus();
await page.keyboard.press('ArrowLeft');
await page.keyboard.press('ArrowLeft');
await page.screenshot({ path: '/tmp/shots/dark-keyboard.png' });
// narrow viewport
await page.setViewportSize({ width: 420, height: 560 });
await page.getByRole('radio', { name: 'Светлая' }).click();
await page.waitForTimeout(100);
await page.screenshot({ path: '/tmp/shots/light-narrow.png' });
console.log('errors:', JSON.stringify(errors));
await browser.close();
EOF
